import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import '../styles/ProductForm.css';

const ProductForm = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [submitError, setSubmitError] = useState('');
  const [submitSuccess, setSubmitSuccess] = useState('');

  const [formData, setFormData] = useState({
    title: '',
    price: '',
    description: '',
    imageUrl: '',
    category: 'Other',
    stock: ''
  });

  const [errors, setErrors] = useState({});

  const categories = ['Electronics', 'Appliances', 'Sports', 'Books', 'Home', 'Fashion', 'Beauty', 'Other'];

  // Validate form
  const validateForm = () => {
    const newErrors = {};

    if (!formData.title.trim()) {
      newErrors.title = 'Title is required';
    } else if (formData.title.length > 100) {
      newErrors.title = 'Title cannot exceed 100 characters';
    }

    if (!formData.price) {
      newErrors.price = 'Price is required';
    } else if (isNaN(formData.price) || parseFloat(formData.price) < 0) {
      newErrors.price = 'Price must be a valid positive number';
    }

    if (!formData.description.trim()) {
      newErrors.description = 'Description is required';
    } else if (formData.description.length > 500) {
      newErrors.description = 'Description cannot exceed 500 characters';
    }

    if (!formData.imageUrl.trim()) {
      newErrors.imageUrl = 'Image URL is required';
    } else if (!isValidUrl(formData.imageUrl)) {
      newErrors.imageUrl = 'Please enter a valid URL';
    }

    if (formData.stock && (isNaN(formData.stock) || parseInt(formData.stock) < 0)) {
      newErrors.stock = 'Stock must be a valid positive number';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // URL validation
  const isValidUrl = (string) => {
    try {
      new URL(string);
      return true;
    } catch (_) {
      return false;
    }
  };

  // Handle input change
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    // Clear error for this field when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validate before submitting
    if (!validateForm()) {
      setSubmitError('Please fix the errors above');
      return;
    }

    setLoading(true);
    setSubmitError('');
    setSubmitSuccess('');

    try {
      console.log('📤 Submitting product:', formData);

      const response = await axios.post('http://localhost:5001/api/products', {
        title: formData.title.trim(),
        price: parseFloat(formData.price),
        description: formData.description.trim(),
        imageUrl: formData.imageUrl.trim(),
        category: formData.category,
        stock: formData.stock ? parseInt(formData.stock) : 0
      });

      if (response.data.success) {
        setSubmitSuccess(`✅ Product "${formData.title}" added successfully!`);
        console.log('✅ Product added:', response.data.product);

        // Reset form
        setFormData({
          title: '',
          price: '',
          description: '',
          imageUrl: '',
          category: 'Other',
          stock: ''
        });

        // Redirect to dashboard after 2 seconds
        setTimeout(() => {
          navigate('/dashboard');
        }, 2000);
      }
    } catch (error) {
      console.error('❌ Error submitting form:', error);
      const errorMessage = error.response?.data?.message || 'Failed to add product. Please try again.';
      setSubmitError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  // Handle reset
  const handleReset = () => {
    setFormData({
      title: '',
      price: '',
      description: '',
      imageUrl: '',
      category: 'Other',
      stock: ''
    });
    setErrors({});
    setSubmitError('');
    setSubmitSuccess('');
  };

  return (
    <div className="product-form-container">
      <div className="form-wrapper">
        <div className="form-header">
          <h2>🛍️ Add New Product</h2>
          <p>Fill in the details below to add a new product to your store</p>
        </div>

        {submitError && (
          <div className="alert alert-error">
            <span className="alert-icon">❌</span>
            {submitError}
          </div>
        )}

        {submitSuccess && (
          <div className="alert alert-success">
            <span className="alert-icon">✅</span>
            {submitSuccess}
          </div>
        )}

        <form onSubmit={handleSubmit} className="product-form">
          {/* Title Field */}
          <div className="form-group">
            <label htmlFor="title">
              Product Title <span className="required">*</span>
            </label>
            <input
              type="text"
              id="title"
              name="title"
              value={formData.title}
              onChange={handleChange}
              placeholder="Enter product title (max 100 characters)"
              maxLength="100"
              className={errors.title ? 'form-control error' : 'form-control'}
            />
            {errors.title && <span className="error-text">{errors.title}</span>}
            <span className="char-count">{formData.title.length}/100</span>
          </div>

          {/* Price Field */}
          <div className="form-group">
            <label htmlFor="price">
              Price <span className="required">*</span>
            </label>
            <div className="input-with-icon">
              <span className="currency-symbol">$</span>
              <input
                type="number"
                id="price"
                name="price"
                value={formData.price}
                onChange={handleChange}
                placeholder="0.00"
                step="0.01"
                min="0"
                className={errors.price ? 'form-control error' : 'form-control'}
              />
            </div>
            {errors.price && <span className="error-text">{errors.price}</span>}
          </div>

          {/* Description Field */}
          <div className="form-group">
            <label htmlFor="description">
              Description <span className="required">*</span>
            </label>
            <textarea
              id="description"
              name="description"
              value={formData.description}
              onChange={handleChange}
              placeholder="Enter product description (max 500 characters)"
              maxLength="500"
              rows="5"
              className={errors.description ? 'form-control error' : 'form-control'}
            ></textarea>
            {errors.description && <span className="error-text">{errors.description}</span>}
            <span className="char-count">{formData.description.length}/500</span>
          </div>

          {/* Image URL Field */}
          <div className="form-group">
            <label htmlFor="imageUrl">
              Image URL <span className="required">*</span>
            </label>
            <input
              type="url"
              id="imageUrl"
              name="imageUrl"
              value={formData.imageUrl}
              onChange={handleChange}
              placeholder="https://example.com/image.jpg"
              className={errors.imageUrl ? 'form-control error' : 'form-control'}
            />
            {errors.imageUrl && <span className="error-text">{errors.imageUrl}</span>}

            {/* Image Preview */}
            {formData.imageUrl && isValidUrl(formData.imageUrl) && (
              <div className="image-preview">
                <p>Preview:</p>
                <img
                  src={formData.imageUrl}
                  alt="Product preview"
                  onError={(e) => {
                    e.target.src = 'https://via.placeholder.com/300?text=Invalid+Image';
                  }}
                />
              </div>
            )}
          </div>

          {/* Category Field */}
          <div className="form-group">
            <label htmlFor="category">Category</label>
            <select
              id="category"
              name="category"
              value={formData.category}
              onChange={handleChange}
              className="form-control"
            >
              {categories.map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>

          {/* Stock Field */}
          <div className="form-group">
            <label htmlFor="stock">Stock Quantity</label>
            <input
              type="number"
              id="stock"
              name="stock"
              value={formData.stock}
              onChange={handleChange}
              placeholder="0"
              min="0"
              className={errors.stock ? 'form-control error' : 'form-control'}
            />
            {errors.stock && <span className="error-text">{errors.stock}</span>}
          </div>

          {/* Form Actions */}
          <div className="form-actions">
            <button
              type="submit"
              className="btn btn-primary"
              disabled={loading}
            >
              {loading ? (
                <>
                  <span className="spinner"></span>
                  Adding Product...
                </>
              ) : (
                '➕ Add Product'
              )}
            </button>
            <button
              type="reset"
              className="btn btn-secondary"
              onClick={handleReset}
              disabled={loading}
            >
              Clear Form
            </button>
            <button
              type="button"
              className="btn btn-tertiary"
              onClick={() => navigate('/dashboard')}
              disabled={loading}
            >
              ← Back to Dashboard
            </button>
          </div>
        </form>

        {/* Form Info */}
        <div className="form-info">
          <p><strong>Required Fields:</strong> Title, Price, Description, Image URL</p>
          <p><strong>Tips:</strong></p>
          <ul>
            <li>Use a valid image URL (JPG, PNG, GIF)</li>
            <li>Placeholder images: https://via.placeholder.com/300?text=YourText</li>
            <li>Prices are stored with 2 decimal places</li>
            <li>Leave stock empty if not tracking inventory</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default ProductForm;
